    test('XdrConfigSettingEntry rejects an undeclared discriminant', () {
      expect(
        () => XdrConfigSettingEntry(XdrConfigSettingID(21)).toXdrJsonValue(),
        throwsA(isA<FormatException>()),
      );
    });
